// Report forms (templates): each engine/forms/<id>/ holds a skeleton.hwpx and a form.json that says
// where the body goes and which of the form's own parts a draft may fill.
//
// form.json
//   id, name, description
//   detect      strings that all appear in a document of this form (empty: the fallback form)
//   body.startAfter  own text of the top-level paragraph the body follows (null: after the title
//                    paragraph, or from the top)
//   body.end    "document" (write up to the end of the document) or
//               { table: { rows, cols, header: [...] } } (write before this top-level table)
//   title       { paragraph, align, spacingAfter } — the paragraph form.title fills (optional)
//   tables.goals    { header, columns, maxRows, align } — a table found by its header text whose
//                   body rows form.goals fills (optional)
//   tables.summary  { columns, maxRows } — body rows of the body.end table that form.summary
//                   fills (optional)
// All forms share the skeleton header's style IDs (paraPr/charPr/borderFill) the engine uses.
import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

export const FORMS_DIR = fileURLToPath(new URL('../forms/', import.meta.url));
export const DEFAULT_FORM = 'research-report';

let cache;

export function listForms() {
  if (!cache) {
    cache = readdirSync(FORMS_DIR, { withFileTypes: true })
      .filter((entry) => entry.isDirectory() && existsSync(join(FORMS_DIR, entry.name, 'form.json')))
      .map((entry) => {
        const form = JSON.parse(readFileSync(join(FORMS_DIR, entry.name, 'form.json'), 'utf8'));
        if (form.id !== entry.name) {
          throw new Error(`form ${entry.name}: form.json id is ${form.id}`);
        }
        return { ...form, skeleton: join(FORMS_DIR, entry.name, 'skeleton.hwpx') };
      })
      .sort((a, b) => a.id.localeCompare(b.id));
  }
  return cache;
}

export function getForm(id) {
  const form = listForms().find((candidate) => candidate.id === id);
  if (!form) {
    throw new Error(`unknown form "${id}"; known forms: ${listForms().map((f) => f.id).join(', ')}`);
  }
  return form;
}

// The form of an existing document: the first form whose detect strings all appear in it, else
// the fallback form (no detect strings), which appends at the end of the document.
export function detectForm(xml) {
  const forms = listForms();
  const specific = forms.find((form) => form.detect.length > 0 && form.detect.every((s) => xml.includes(s)));
  if (specific) {
    return specific;
  }
  const fallback = forms.find((form) => form.detect.length === 0);
  if (!fallback) {
    throw new Error('no fallback form (a form with no detect strings) is installed');
  }
  return fallback;
}
